import { WSReqType } from "game-server/ws";
import { useEffect } from "react";
import settings from "settings";
import { useSubscribedTeam } from "stores/ClientGlobalStateStore";
import { useServerInteractionStore } from "stores/ServerInteractionStore";

const PENDING_CLASS = "locked-puzzle-pending";
const LOCKED_CLASS = "locked-puzzle";

/**
 * Returns the name of the puzzle that this Django-served page belongs to
 * if the page should be gated behind the puzzle being unlocked.
 */
export const getLockedPuzzlePromptPuzName = (): string | null => {
  // Only postsolvers can end up on a puzzle page that they haven't unlocked,
  // since the page is static and no longer checked by Django.
  if (!settings.isPosthunt) return null;
  const match = window.location.pathname.match(
    /^\/(?:puzzle|solve|solution)\/([^/]+?)(?:\.html)?\/?$/
  );
  return match === null ? null : decodeURIComponent(match[1]);
};

/** Hides the page content until we know whether the puzzle is unlocked. */
export const hidePageForLockedPuzzlePrompt = () => {
  document.body.classList.add(PENDING_CLASS);
};

/**
 * In posthunt, asks the postsolver whether to unlock a puzzle ahead of
 * time when they open one of its pages without having unlocked it.
 */
const LockedPuzzlePrompt = ({ puzName }: { puzName: string }) => {
  const serverInterfaceController = useServerInteractionStore(
    (state) => state.getServerInterfaceController
  )();
  const subscribedTeam = useSubscribedTeam();
  const teamId = subscribedTeam?.teamId ?? null;
  const isLocked =
    subscribedTeam === null
      ? null
      : subscribedTeam.puzzles[puzName] === undefined;

  useEffect(() => {
    if (isLocked === null) return;
    document.body.classList.remove(PENDING_CLASS);
    document.body.classList.toggle(LOCKED_CLASS, isLocked);
  }, [isLocked]);

  if (!(isLocked ?? false)) return null;

  return (
    <main className="locked-puzzle-prompt">
      <p>
        You haven’t unlocked this puzzle yet, but you can ignore your current
        hunt progress and unlock this puzzle anyway. There might be spoilers for
        parts of the hunt you haven’t yet reached.
      </p>
      <p>Do you wish to continue?</p>
      <div className="locked-puzzle-buttons">
        <button
          className="btn"
          disabled={serverInterfaceController === null || teamId === null}
          onClick={() => {
            if (serverInterfaceController === null || teamId === null) return;
            serverInterfaceController.sendReq({
              type: WSReqType.ADMIN_MODIFY,
              teams: {
                [teamId]: { overrideUnlocked: { [puzName]: true } },
              },
            });
          }}
        >
          Yes, unlock this puzzle
        </button>
        <a className="btn" href={`${settings.djangoBaseUrl}game/map`}>
          No, take me back
        </a>
      </div>
    </main>
  );
};

export default LockedPuzzlePrompt;
